ucs.falcon_logscale_query:
(#event_simpleName=ProcessRollup2 OR #event_simpleName=FileWritten)
| case {
    #event_simpleName=FileWritten TargetFileName=/\\(RentDrv2|TrueSight|ZAMGuard64|zam64|ZAM|procexp152|gmer64)\.sys$/i
    | groupBy([aid, ComputerName], function=collect([TargetFileName, ContextImageFileName, ContextProcessId], multival=true)) ;
    #event_simpleName=ProcessRollup2 ImageFileName=/\\sc\.exe$/i CommandLine=/create.*type=\s*kernel/i
    | groupBy([aid, ComputerName], function=collect([CommandLine, ParentBaseFileName], multival=true)) ;
    #event_simpleName=ProcessRollup2 ImageFileName=/\\(taskkill|net|sc)\.exe$/i CommandLine=/(MsSense|MsMpEng|SentinelAgent|CSFalconService|CylanceSvc|Sophos|WinDefend|xagt|ekrn)/i
    | groupBy([aid, ComputerName], function=collect([CommandLine], multival=true))
  }
| groupBy([aid, ComputerName], function=count(as=stages))
| stages>=2
